<?php
require_once __DIR__ . '/auth.php';
require_once __DIR__ . '/vehicle_data.php';
$user = require_signed_in();
start_user_session();
$catalogue = vehicle_catalogue();
$favouriteIds = $_SESSION['favourites'] ?? array();
$recentIds = $_SESSION['recent_vehicles'] ?? array();
$find = function ($id) use ($catalogue) { foreach ($catalogue as $vehicle) { if ($vehicle['id'] === $id) return $vehicle; } return null; };
?>
